<?php declare(strict_types=1);namespace App\Controllers;use App\Core\Auth;use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Models\Order;use App\Models\Plan;use App\Models\User;use App\Services\CouponService;use App\Services\InvoiceService;use App\Services\OrderService;use App\Services\StripeService;final class CheckoutController extends Controller{public function start(Request $d):Response{return $this->redirect(url('/pricing'));}public function plan(Request $h,string $u):Response{$C=Plan::findBySlug($u);if(!$C||!(int)$C['is_active']||$C['slug']==='trial'){$this->flash('error',t('checkout.plan_unavailable'));return $this->redirect(url('/pricing'));}$v=$h->str('period')==='year'?'year':'month';Session::set('checkout',['plan'=>$u,'period'=>$v,'coupon'=>Session::get('checkout')['coupon']??null]);if(!Auth::check()){Session::set('intended',url('/checkout/'.$u.'/billing'));return $this->view('checkout/account',['plan'=>$C,'period'=>$v,'meta'=>['title'=>t('checkout.title')]]);}return $this->redirect(url('/checkout/'.$u.'/billing'));}public function billing(Request $S,string $s):Response{$n=Plan::findBySlug($s);if(!$n){return $this->redirect(url('/pricing'));}$b=Session::get('checkout',['period'=>'month']);$V=$S->str('period')?:$b['period']??'month';$r=$this->user();$m=!empty($b['coupon'])?CouponService::validate($b['coupon'],$s)['coupon']:null;$p=Plan::price($n,$V);$X=$m?CouponService::discount($m,$p):0;$O=InvoiceService::compute($p,$X,(string)($S->str('country')?:$r['country']),$S->str('vat_number')?:$r['vat_number']);return $this->view('checkout/billing',['plan'=>$n,'period'=>$V,'coupon'=>$m,'calc'=>$O,'user'=>$r,'countries'=>self::countries(),'meta'=>['title'=>t('checkout.title')]]);}public function billingSave(Request $Z,string $b):Response{$j=Plan::findBySlug($b);if(!$j||!(int)$j['is_active']){return $this->redirect(url('/pricing'));}$B=['name'=>'required|max:191','address_line1'=>'required|max:191','postal_code'=>'required|max:32','city'=>'required|max:128','country'=>'required|regex:/^[A-Z]{2}$/','company'=>'max:191','vat_number'=>'vat|max:32','period'=>'in:month,year'];if($v=$this->validate($Z,$B,url('/checkout/'.$b.'/billing'))){return $v;}$E=$this->user();User::update((int)$E['id'],['name'=>$Z->str('name'),'company'=>$Z->str('company')?:null,'vat_number'=>$Z->str('vat_number')?strtoupper(preg_replace('/\s+/','',$Z->str('vat_number'))):null,'address_line1'=>$Z->str('address_line1'),'address_line2'=>$Z->str('address_line2')?:null,'postal_code'=>$Z->str('postal_code'),'city'=>$Z->str('city'),'country'=>strtoupper($Z->str('country')),'phone'=>$Z->str('phone')?:null]);$E=User::find((int)$E['id']);$P=$Z->str('period')==='year'?'year':'month';$k=Session::get('checkout',[]);$t=!empty($k['coupon'])?CouponService::validate($k['coupon'],$b)['coupon']:null;$H=$k['kind']??'new';$n=isset($k['license_id'])?(int)$k['license_id']:null;$A=OrderService::create($E,$j,$P,$t,$H,$n);Session::set('checkout',array_merge($k,['period'=>$P,'order_id'=>(int)$A['id']]));return $this->redirect(url('/checkout/pay/'.$A['id']));}public function applyCoupon(Request $s):Response{$A=Session::get('checkout',[]);$v=(string)($A['plan']??$s->str('plan'));$a=$s->str('coupon');if($a===''){$A['coupon']=null;Session::set('checkout',$A);return $this->back();}$m=CouponService::validate($a,$v);if($m['coupon']){$A['coupon']=$m['coupon']['code'];$this->flash('success',t('coupon.applied'));}else{$A['coupon']=null;$this->flash('error',t($m['error']));}Session::set('checkout',$A);return $this->back(url('/checkout/'.$v.'/billing'));}public function pay(Request $i,string $y):Response{$o=Order::find((int)$y);if(!$o||(int)$o['user_id']!==Auth::id()){return $this->redirect(url('/pricing'));}if($o['status']==='paid'){return $this->redirect(url('/checkout/success/'.$o['id']));}$g=Plan::find((int)$o['plan_id']);$a=StripeService::mode();if($a==='stripe'){try{$w=StripeService::createCheckoutSession($o,$g,$this->user(),OrderService::label($o,$g));Order::update((int)$o['id'],['payment_ref'=>$w['id'],'payment_provider'=>'stripe']);return $this->redirect($w['url']);}catch(\Throwable $f){tp_log('stripe',$f->getMessage());$this->flash('error',t('checkout.payment_error'));return $this->redirect(url('/checkout/'.$g['slug'].'/billing'));}}return $this->view('checkout/pay',['order'=>$o,'plan'=>$g,'mode'=>$a,'meta'=>['title'=>t('checkout.payment')]]);}public function sandboxPay(Request $n,string $I):Response{$a=Order::find((int)$I);if(!$a||(int)$a['user_id']!==Auth::id()||$a['status']==='paid'){return $this->redirect(url('/account'));}$y=StripeService::mode();if($y==='manual'){Order::update((int)$a['id'],['status'=>'awaiting_transfer','payment_provider'=>'manual']);$this->flash('success',t('checkout.transfer_registered'));return $this->redirect(url('/account/invoices'));}if($n->str('outcome')==='fail'){Order::update((int)$a['id'],['status'=>'failed']);$this->flash('error',t('checkout.payment_declined'));return $this->redirect(url('/checkout/cancel/'.$a['id']));}OrderService::markPaid($a,'sandbox','sandbox_'.bin2hex(random_bytes(6)));return $this->redirect(url('/checkout/success/'.$a['id']));}public function success(Request $m,string $y):Response{$a=Order::withRelations((int)$y);if(!$a||(int)$a['user_id']!==Auth::id()){return $this->redirect(url('/account'));}if($a['status']!=='paid'&&StripeService::mode()==='stripe'&&$m->str('session_id')!==''){try{$i=StripeService::retrieveSession($m->str('session_id'));if(($i['payment_status']??'')==='paid'&&(string)($i['client_reference_id']??'')===(string)$a['id']){OrderService::markPaid($a,'stripe',$i['payment_intent']??$i['id']);$a=Order::withRelations((int)$y);}}catch(\Throwable $G){tp_log('stripe','success check: '.$G->getMessage());}}Session::remove('checkout');$c=$a['license_id']?\App\Models\License::find((int)$a['license_id']):null;$C=\App\Models\Invoice::forOrder((int)$a['id']);return $this->view('checkout/success',['order'=>$a,'license'=>$c,'invoice'=>$C,'meta'=>['title'=>t('checkout.success_title')]]);}public function cancel(Request $p,string $D):Response{$h=Order::withRelations((int)$D);if(!$h||(int)$h['user_id']!==Auth::id()){return $this->redirect(url('/pricing'));}if($h['status']==='pending'){Order::update((int)$h['id'],['status'=>'cancelled']);}return $this->view('checkout/cancel',['order'=>$h,'meta'=>['title'=>t('checkout.cancelled_title')]]);}public static function countries():array{return['FR'=>'France','BE'=>'Belgique','CH'=>'Suisse','LU'=>'Luxembourg','DE'=>'Deutschland','ES'=>'España','IT'=>'Italia','PT'=>'Portugal','NL'=>'Nederland','GB'=>'United Kingdom','IE'=>'Ireland','AT'=>'Österreich','PL'=>'Polska','CZ'=>'Česko','SE'=>'Sverige','DK'=>'Danmark','FI'=>'Suomi','NO'=>'Norge','GR'=>'Ελλάδα','RO'=>'România','BG'=>'България','HU'=>'Magyarország','HR'=>'Hrvatska','SI'=>'Slovenija','SK'=>'Slovensko','EE'=>'Eesti','LV'=>'Latvija','LT'=>'Lietuva','CY'=>'Κύπρος','MT'=>'Malta','US'=>'United States','CA'=>'Canada','MA'=>'Maroc','TN'=>'Tunisie','DZ'=>'Algérie','SN'=>'Sénégal','CI'=>"Côte d'Ivoire",'TR'=>'Türkiye','UA'=>'Україна','RU'=>'Россия','IN'=>'India','BD'=>'Bangladesh','ID'=>'Indonesia','VN'=>'Việt Nam','TH'=>'ไทย','CN'=>'中国','JP'=>'日本','KR'=>'한국','BR'=>'Brasil','MX'=>'México','AR'=>'Argentina','AU'=>'Australia','NZ'=>'New Zealand','ZA'=>'South Africa','AE'=>'الإمارات','SA'=>'السعودية','EG'=>'مصر'];}}